Matrix features = Matrix.fromRows(new double[][] {
    {0.0, 0.0}, {0.2, 0.1}, {0.1, 0.3},
    {5.0, 5.0}, {5.2, 4.9}, {4.8, 5.1}
});
AgglomerativeClustering model = AgglomerativeClustering.builder()
        .clusters(2)
        .linkage(AgglomerativeClustering.Linkage.WARD)
        .build()
        .fit(features);
int[] labels = model.labels();
double[] assigned = model.predict(features);

Matrix features = Matrix.fromRows(new double[][] {
    {0.0, 0.0}, {0.3, 0.1}, {0.1, 0.4},
    {5.0, 5.0}, {5.2, 4.8}, {4.9, 5.3},
    {9.0, 0.5}
});
DBSCAN dbscan = DBSCAN.builder()
        .eps(0.6)
        .minPoints(3)
        .metric(DistanceMetric.EUCLIDEAN)
        .build()
        .fit(features, null);
int[] labels = dbscan.labels();
int clusters = dbscan.clusterCount();
int noise = dbscan.noiseCount();

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}, {2, 2}, {2, 1}});
double[] y = {0, 0, 1, 1, 1, 1};
DataSplit.Holdout split = DataSplit.holdout(x, y, 0.25, 42L);
LinearRegression model = LinearRegression.builder().build()
        .fit(split.trainFeatures(), split.trainTargets());
double[] predicted = model.predict(split.testFeatures());

Matrix x = Matrix.fromRows(new double[][]{
        {0.0, 1.0},
        {1.0, 1.0},
        {1.0, 0.0},
        {2.0, 0.0}});
double[] y = {0.0, 0.0, 1.0, 1.0};

DecisionTree tree = DecisionTree.builder()
        .task(TreeTask.CLASSIFICATION)
        .criterion(ImpurityCriterion.GINI)
        .maxDepth(3)
        .minSamplesLeaf(1)
        .bins(32)
        .seed(7L)
        .build()
        .fit(x, y);

double[] predicted = tree.predict(x);
double[] importance = tree.featureImportances();

double[] a = {1.0, 2.0, 3.0};
double[] b = {1.0, 4.0, 3.0};
double euclidean = DistanceMetric.EUCLIDEAN.distance(a, 0, b, 0, 3);
double manhattan = DistanceMetric.MANHATTAN.distance(a, 0, b, 0, 3);

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}});
double[] y = {0, 1, 1, 0};
Estimator model = KNearestNeighbors.builder().k(3).build().fit(x, y);
double[] prediction = model.predict(x);

Matrix x = Matrix.fromRows(new double[][]{
        {0.0, 1.0}, {1.0, 1.0}, {1.0, 0.0}, {2.0, 0.0}});
double[] y = {0.0, 0.0, 1.0, 1.0};
DecisionTree tree = DecisionTree.builder()
        .task(TreeTask.CLASSIFICATION)
        .maxDepth(3)
        .build()
        .fit(x, y);

double[] impurity = FeatureImportance.of(tree);
FeatureImportance.PermutationResult permuted = FeatureImportance.permutationImportance(
        tree, x, y, JSL.Metric.ACCURACY, 5, 42L);
double[] mean = permuted.importancesMean();
int[] order = permuted.rankedFeaturesDescending();

Matrix features = Matrix.fromRows(new double[][] {
    {1.0, 2.0}, {1.2, 1.8}, {0.9, 2.1},
    {5.0, 8.0}, {5.4, 7.6}, {4.8, 8.2}
});
double[] targets = {0.0, 0.0, 0.0, 1.0, 1.0, 1.0};
GaussianNaiveBayes model = GaussianNaiveBayes.builder()
        .varianceSmoothing(1e-9)
        .build()
        .fit(features, targets);
double[] predicted = model.predict(features);
Matrix logPosterior = model.predictLogProbability(features);
Matrix posterior = model.predictProbability(features);
